var ph = PhaseManager.get_current_phase_instance()
var n := 0
for d in ph.dice_log:
	if str(d.get("context", "")) == "damage_modifier" and str(d.get("source", "")) == "Praesidium Shield":
		n += 1
		print("[wp-c7] praesidium dice line: ", d.get("message", ""))
var lost := 99 - int(GameState.get_unit("U_SHIELD_CAPTAIN_A").models[0].get("current_wounds", 99))
print("[wp-c7] praesidium: lines=", n, " wounds lost=", lost)
return n >= 1 and lost == 2 * n

var panel = tree.root.get_node("Main").get_node_or_null("HUD_Left/GameLogPanel")
if panel == null:
	for n in tree.root.get_node("Main").find_children("*", "", true, false):
		if n.get("_tab_dice_button") != null:
